        "type": "API",
        "input": {
          "testID": "string",
          "testPayload": "struct"
        },
        "output": "testResults"
      }
    },
    "mechanisms": {
      "sessionHeartbeat": {
        "trigger": "time-based",
        "interval": "1 minute",
        "action": "logContextState"
      },
      "workClaim": {
        "input": "taskDescriptor",
        "output": "taskID"
      },
      "workSettle": {
        "input": "taskID",
        "output": "settlementConfirmation"
      }
    },
