        }
      },
      "actionSuccess": {
        "input": {
          "taskID": "string",
          "expectedOutcome": "struct"
        },
        "output": "isConfirmed"
      }
    }
  },
  "smallestRealVerticalSlice": {
    "name": "TextFileEdit",
    "actions": [
      {
        "type": "boundedRead",
        "input": "textFileID",
        "output": "textContent"
      },
      {
        "type": "boundedEdit",
        "input": {
          "resourceID": "textFileID",
          "editPayload": {
            "newContent": "modifiedText"
          }
        },
        "output": "editConfirmation"
      },
      {
        "type": "boundedTest",
        "input": {
          "testID": "basicValidation",
          "testPayload": {
            "resourceID": "textFileID"
          }
        },
        "output": "testResults"
      }
    ]
  }
}

